import{_ as i,b as a,c as l,f as t}from"./chunks/framework.86O3EbG5.js";const f=JSON.parse('{"title":"知识图谱导论（七）","description":"","frontmatter":{"title":"知识图谱导论（七）","subTitle":"知识图谱总结","author":"oasis","date":"2026-03-05T00:00:00.000Z"},"headers":[],"relativePath":"articles/artificial-intelligence/books/zhi-shi-tu-pu-dao-lun/7.md","filePath":"articles/artificial-intelligence/books/zhi-shi-tu-pu-dao-lun/7.md"}'),s={name:"articles/artificial-intelligence/books/zhi-shi-tu-pu-dao-lun/7.md"};function o(n,e,r,c,u,p){return a(),l("div",null,[...e[0]||(e[0]=[t("p",null,"知识图谱是一种类似人类先验知识的表示，它可以缓解大语言模型的幻觉问题。对知识图谱进行拆分，涉及知识的表示、知识的存储、知识图谱的融合、知识图谱的应用。 知识的表示通过三元组（实体、关系、对象）来实现，为了得到三元组，涉及到从文本中提取实体、提取概念、提取关系。",-1),t("p",null,"知识图谱的存储通过分析关系数据库存储的弊端：例如大量连表查询，插入数据性能低下，关系被隐藏在外键中。为了解决这些问题，出现了以关系为一等公民的图数据库。",-1)])])}const _=i(s,[["render",o]]);export{f as __pageData,_ as default};
